INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A dyeing recipe calls for 2.5% owf of a reactive dye. For a batch of 350 kg fabric, how many kg of dye are needed?', '["8.75 kg","2.5 kg","35 kg","0.875 kg"]'::jsonb, '8.75 kg', 'Dye needed = %owf × fabric weight = 0.025 × 350 kg = 8.75 kg.', 1, '{"dye-recipe-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A dyeing recipe calls for 0.8% owf of a reactive dye. For a batch of 1,200 kg fabric, how many kg of dye are needed?', '["9.6 kg","0.8 kg","96 kg","15 kg"]'::jsonb, '9.6 kg', 'Dye needed = %owf × fabric weight = 0.008 × 1,200 kg = 9.6 kg.', 1, '{"dye-recipe-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A dyeing machine uses a liquor ratio of 1:6 for a 700 kg fabric batch. How many liters of dye liquor are needed?', '["4,200 liters","700 liters","116.7 liters","6 liters"]'::jsonb, '4,200 liters', 'Liquor volume = liquor ratio × fabric weight = 6 × 700 kg = 4,200 liters.', 1, '{"liquor-ratio-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A dyeing machine uses a liquor ratio of 1:15 for a 150 kg fabric batch. How many liters of dye liquor are needed?', '["2,250 liters","150 liters","10 liters","15 liters"]'::jsonb, '2,250 liters', 'Liquor volume = liquor ratio × fabric weight = 15 × 150 kg = 2,250 liters.', 1, '{"liquor-ratio-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A recipe requires 50 g/L of salt at a liquor ratio of 1:8 for a 400 kg fabric batch. How many kg of salt are needed?', '["160 kg","50 kg","8 kg","400 kg"]'::jsonb, '160 kg', 'Total liquor = 8 × 400 kg = 3,200 liters. Total salt = 50 g/L × 3,200 L = 160,000 g = 160 kg.', 2, '{"salt-dosing-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A recipe requires 65 g/L of soda ash at a liquor ratio of 1:10 for a 300 kg fabric batch. How many kg of soda ash are needed?', '["195 kg","65 kg","10 kg","300 kg"]'::jsonb, '195 kg', 'Total liquor = 10 × 300 kg = 3,000 liters. Total soda ash = 65 g/L × 3,000 L = 195,000 g = 195 kg.', 2, '{"alkali-dosing-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A dye bath achieves 88% exhaustion for a recipe using 2.5% owf dye on a 500 kg fabric batch. Approximately how much dye (in kg) remains unexhausted?', '["≈ 1.5 kg","≈ 12.5 kg","≈ 11 kg","≈ 2.5 kg"]'::jsonb, '≈ 1.5 kg', 'Total dye = 0.025 × 500 kg = 12.5 kg. Exhausted = 88% of 12.5 kg = 11 kg. Unexhausted = 12.5 − 11 = 1.5 kg.', 2, '{"dye-exhaustion-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A dye bath achieves 90% exhaustion for a recipe using 1.8% owf dye on a 800 kg fabric batch. Approximately how much dye (in kg) remains unexhausted?', '["≈ 1.44 kg","≈ 14.4 kg","≈ 12.96 kg","≈ 1.8 kg"]'::jsonb, '≈ 1.44 kg', 'Total dye = 0.018 × 800 kg = 14.4 kg. Exhausted = 90% of 14.4 kg = 12.96 kg. Unexhausted = 14.4 − 12.96 = 1.44 kg.', 2, '{"dye-exhaustion-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A fabric''s greige weight is 300 kg, and after wet processing it weighs 279 kg. What is the approximate processing weight loss percentage?', '["7%","93%","21%","2.7%"]'::jsonb, '7%', 'Weight loss % = ((greige weight − finished weight) / greige weight) × 100 = ((300 − 279) / 300) × 100 = 7%.', 1, '{"processing-weight-loss-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A fabric''s greige weight is 900 kg, and after wet processing it weighs 828 kg. What is the approximate processing weight loss percentage?', '["8%","92%","72%","0.8%"]'::jsonb, '8%', 'Weight loss % = ((900 − 828) / 900) × 100 = (72/900) × 100 = 8%.', 1, '{"processing-weight-loss-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A padder shows 68% wet pickup. For 500 kg of dry fabric entering the padder, what is the total wet weight after padding?', '["840 kg","500 kg","340 kg","568 kg"]'::jsonb, '840 kg', 'Wet weight = dry weight × (1 + wet pickup%) = 500 × 1.68 = 840 kg.', 2, '{"wet-pickup-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A padder shows 72% wet pickup. For 250 kg of dry fabric entering the padder, what is the total wet weight after padding?', '["430 kg","250 kg","180 kg","322 kg"]'::jsonb, '430 kg', 'Wet weight = dry weight × (1 + wet pickup%) = 250 × 1.72 = 430 kg.', 2, '{"wet-pickup-calc"}'::text[]);
